// Submits the message the CRM already built, unchanged.
//
// WHY THIS IS A CODE NODE AND NOT "Send Email" OR THE GMAIL NODE.
//
// Gmail is wrong for this outright: it sends from a Google mailbox, so the
// message would not be signed d=devlabconnect.com, would not come from our
// MTA, and Google prohibits cold outreach in its program policies.
//
// n8n's Send Email node is closer but still cannot do three things this path
// needs, and its own documentation says so: it "does not support setting
// headers like In-Reply-To and References", it exposes no way to pin a
// Message-ID, and it gives nodemailer no envelope, so MAIL FROM is always
// derived from the From: header.
//
// Each of those failures is invisible from here -- the send succeeds. What
// breaks is downstream: a bounce comes back carrying no identifier we issued,
// so it can only be matched by the recipient address it names, and an address
// is an assertion any sender can make. Our bounce path does not trust that to
// suppress, so outreach hard bounces would need a human forever.
//
// So the CRM emits a complete RFC 5322 message plus an explicit envelope, and
// this node only issues MAIL FROM, RCPT TO, DATA.
//
// REQUIRES on the n8n container (or the Task Runner, if one is used):
//   NODE_FUNCTION_ALLOW_EXTERNAL=nodemailer
// Without it require() is blocked and this fails closed -- nothing is sent and
// the draft is reported failed rather than silently dropped.

const nodemailer = require('nodemailer')

const message = $input.item.json

// The private Docker mail network. Postfix trusts ONLY this container's IP
// plus localhost and has no listener reachable from the internet. Do not point
// this at a public address, and do not widen Postfix mynetworks to suit it.
const transporter = nodemailer.createTransport({
  host: $env.DEVLAB_SMTP_HOST || '172.19.0.1',
  port: Number($env.DEVLAB_SMTP_PORT || 25),
  secure: false,
  // The hop to Postfix is over a private network on the same host and Postfix
  // presents a self-signed certificate there. TLS to the RECIPIENT is
  // negotiated by Postfix itself and is unaffected by this.
  tls: { rejectUnauthorized: false },
})

const info = await transporter.sendMail({
  // Both are required together: nodemailer does not parse an envelope out of a
  // raw message, and this envelope sender is the per-draft VERP address that
  // lets a bounce find the draft it belongs to.
  envelope: { from: message.envelope.from, to: message.envelope.to },
  raw: message.raw,
})

return {
  json: {
    draftId: message.draftId,
    providerMessageId: info.messageId || null,
    accepted: info.accepted || [],
    rejected: info.rejected || [],
  },
}
